        if (!/^(chat:[^:]+:message:[^:]+|phone:[^:]+:message:[^:]+|opening:[^:]+:revision:\d+)$/.test(log.source_message_id))
            issue(['event_log', id, 'source_message_id'], '履历来源须由运行时注入规范消息引用，不能保留临时令牌或猜测的ID');
