            issue(['knowledge', 'facts', id], '事实需要具体内容及来源');
        if (fact.source_log_id !== null && !Object.hasOwn(stat.event_log, fact.source_log_id))
            issue(['knowledge', 'facts', id, 'source_log_id'], '引用的事件履历不存在');
