        checkControlledKeys(message.recipients, ['phone', 'messages', id, 'recipients']);
        const thread = stat.phone.threads[message.thread_id];
        if (!Object.hasOwn(stat.phone.threads, message.thread_id))
            issue(['phone', 'messages', id, 'thread_id'], '消息引用的会话不存在');
        if (message.state === 'sent' && (!hasText(message.body) || !hasText(message.sender) || Object.keys(message.recipients).length === 0))
            issue(['phone', 'messages', id], '已发送消息需要正文、发送者与当时接收者');
        if (message.state === 'sent' && !message.participants_at_send[message.sender])
            issue(['phone', 'messages', id, 'participants_at_send'], '发送者必须属于发送时的会话成员');
        for (const recipient of Object.keys(message.recipients))
            if (!message.participants_at_send[recipient])
                issue(['phone', 'messages', id, 'recipients', recipient], '接收者必须属于发送时的会话成员');
