  if(context.nodeId==='M00' && (context.location!=='教师办公室' || !/学生|在校生|高中生/.test(context.identityKind)))guidance='承接已经呈现的开场和玩家本人的真实来意。按当前去处继续，介绍与社团参与由实际回应形成。';
  const lines=['<当前剧情>','时间节点: '+context.nodeId+' '+node.名称,'当前发展: '+guidance,
    '演绎: 回应玩家现在的来意；关键时刻给两至三项可行行动，也接受自由回答。移动、答应与恋爱按实际回应发生。'];
  if(context.control?.mode==='cast')lines.push('玩家身份: '+storyEscape(context.control.canonical_name)+'。此人的台词、动作和决定承接玩家输入；其他人物分别回应。');
  if(context.hookId){
    const hook=catalog.hooks[context.hookId];
    lines.push('当前入口: '+context.hookId+' '+hook.名称);
    if(context.remote)lines.push('交流方式: 已有通信，只写远程交流，不写同处一室。');
    const self=context.self?catalog.selfHooks[context.hookId]:null;
    if(context.mode==='new')lines.push('眼前: '+observed(self?self.眼前:context.remote?'沿有子已发来的实际消息交流，先核对她提到的那个前提。':hook.眼前));
    else lines.push('续接方式: 眼前事情已经发生，回应玩家当前的话，沿已知经过继续，不重新演初遇。');
    lines.push('可以继续: '+observed(self?self.接话:hook.接话));
    if(Object.keys(context.aliases??{}).length)lines.push('初次见面: 使用眼前已观察的称呼，相识与姓名按实际介绍建立。');
    lines.push('记录: 正文实际采用后才更新 events.'+context.eventId+'，results.hook_id='+context.hookId+'；看见机会先记已提及，回应后才记进行中，收束或离开按真实结果记录。');
  }
  if(context.mai)lines.push('异常续接: '+catalog.maiGuidance+' 当前记忆与感知按观察者分别处理，帮助成功后再谈双方的关系。');
  const visit={visit_date:context.date,visit_location:context.location,visit_started_turn:String(context.visitStartedTurn)};
  if(context.hookId){visit.last_hook_id=context.hookId;visit.last_hook_visit=context.visitKey;}
  lines.push('到访记录: 正文采用后记录 '+JSON.stringify(visit).replace(/[<>&%]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'))+'；转场按真实到达，已结束的事沿结果继续。',
    context.mainlineExists?'主线已有：仅 add/replace /events/semester_mainline/results/<键>，保留其他results。':'主线未建：先 add /events/semester_mainline 整条事件对象，results含上述到访。',
    '主线履历及source_log_ids由运行端绑定真实回复，正文不填写；current_node由运行端派生。','</当前剧情>');
  const out=lines.join('\n');
