  for(const id of eventIds){const x=e.events[id];events[id]={state:x.state,results:compact(Object.fromEntries(Object.entries(storyObject(x.results)).filter(([k])=>['hook_id','stage','player_remembers','current_node'].includes(k))),60)};}
