  const event_log={};
  for(const id of logIds){const l=e.logs[id];event_log[id]={event_id:l.event_id,date:l.date,time:l.time,player_action:storyText(l.player_action,100),result:storyText(l.result,100)};}
  const factIds=Object.entries(e.facts).filter(([id,f])=>e.knownFact(id,f) && logIds.includes(f.source_log_id)).slice(0,3);
  const facts=Object.fromEntries(factIds.map(([id,f])=>[id,{claim:storyText(f.claim,100),truth_status:f.truth_status,source_log_id:f.source_log_id}]));
  const perception={};
  const perceptionTargets=[...(context.onsite??[])];
  if(context.hookId==='H20'){
    const ghost=e.s.characters?.['庚夕子'];
    if(ghost?.present===true && storyLocation(ghost.location)===context.location && !!storyText(ghost.location_basis) && Object.values(storyObject(e.s.knowledge?.perception?.['庚夕子'])).some(p=>Object.keys(storyObject(p?.source_fact_ids)).some(id=>e.knownFact(id,e.facts[id]))))perceptionTargets.unshift('庚夕子');
  }
