          logs: Object.fromEntries(Object.entries(logs).map(([id, log]) => [id, { ...log, phone_effects: undefined }])),
          facts: Object.fromEntries(Object.entries(facts).map(([id, fact]) => [id, { subject: fact.subject, claim: fact.claim, source_log_id: fact.source_log_id, learned_by_player: fact.known_by.player }])),
