function localOpportunity(location) {
  if (/学生会/.test(location)) return '桌上放着今天要核对的活动报名表，最后一栏还空着。';
  if (/奉仕部/.test(location)) return '活动室的门敞着，桌边多了一封没有署名的委托信。';
  if (/琴|音乐|练习室|轻音/.test(location)) return '门边贴着新的练习室预约表，有两个时段被画上了同样的记号。';
  if (/图书|书店|文学|古典/.test(location)) return '书桌上留着一本夹有便条的书，便条只写了一个还没说完的问题。';
  if (/旧校舍|旧走廊|旧活动室/.test(location)) return '窗边的旧目录被风翻开，新贴的房间编号与纸上的记录对不上。';
  if (/办公室|教职|职员|教室|班$/.test(location)) return '桌上的活动通知刚送到，今天的安排还等着一个答复。';
  if (/体育|球场|操场/.test(location)) return '场边贴着今天的场地安排，下一场活动的器材还没有搬过去。';
  if (/咖啡|餐厅|厨房/.test(location)) return '门边的铃响了一声，一张活动邀请被放在了桌上。';
  if (/家|公寓|卧室|宿舍/.test(location)) return '窗外的天色还亮着，桌上放着一张学校公开活动的通知。';
  return '附近的公告栏刚换上了这个学期的活动安排，一份空白报名表留在旁边。';
}

