  for(const key of ['GENERATION_ENDED','GENERATION_STOPPED'])if(tavernEvents[key])add(eventOn,tavernEvents[key],()=>{nativeGenerating=false;if(key==='GENERATION_STOPPED'){const row=getChatMessages(-1,{include_swipes:false}).at(-1);if(row?.role==='assistant')nativeStopped={chat_id:getCurrentChatId(),message_id:row.message_id,swipe_id:getMessageObject(row.message_id)?.swipe_id??0,body:row.message};}if(cgPending)queueCg();});
