      context.finish_callbacks.push(()=>{try{const emitted=eventEmit('crossover_reply_settled',{chat_id:context.chat_id,message_id:context.message_id,swipe_id:context.swipe_id,state:context.aborted||job.failed?'failed':'saved'});emitted?.catch?.(onError);}catch(error){onError(error);}});
