      const visible = Object.entries(stat.phone.messages).filter(([, message]) => message.thread_id === threadId && message.state === 'sent' && message.participants_at_send.player && (message.sender === 'player' || message.recipients.player))
        .sort((a, b) => `${a[1].date} ${a[1].time} ${a[0]}`.localeCompare(`${b[1].date} ${b[1].time} ${b[0]}`));
      const target = visible.findIndex(([id]) => id === messageId), current = thread.last_read_message_id === null ? -1 : visible.findIndex(([id]) => id === thread.last_read_message_id);
