// Presentation only: scores never award relationship facts.
const relationStyles = Object.freeze({
  恋人: { icon: 'hearts', tone: 'rose', rank: 0 },
  家人: { icon: 'home', tone: 'peach', rank: 1 },
  挚友: { icon: 'stars', tone: 'gold', rank: 2 },
  闺蜜: { icon: 'ribbon', tone: 'pink', rank: 3 },
  知己: { icon: 'chat', tone: 'violet', rank: 4 },
  搭档: { icon: 'puzzle', tone: 'blue', rank: 5 },
  竞争对手: { icon: 'flags', tone: 'mint', rank: 6 },
  宿敌: { icon: 'swords', tone: 'indigo', rank: 7 },
  死敌: { icon: 'thorns', tone: 'crimson', rank: 8 },
  冷战: { icon: 'snow', tone: 'ice', rank: 9 },
  前任: { icon: 'broken', tone: 'mauve', rank: 10 },
  朋友: { icon: 'chat', tone: 'blue', rank: 99 },
});
const relationships_text = v => typeof v === 'string' ? v.trim() : '';
const score = v => Math.max(0, Math.min(100, Number(v) || 0));
function relationshipBadges(relationship = {}) {
  const badges = [];
  const push = (name, basis, since = '') => {
    if (!relationships_text(basis)) return;
    badges.push({ name, basis: relationships_text(basis), since: relationships_text(since), ...(Object.hasOwn(relationStyles, name) ? relationStyles[name] : { icon: 'seal', tone: 'violet', rank: 50 }) });
  };
  if (relationship.commitment === '恋人') push('恋人', relationship.commitment_basis);
  for (const [name, fact] of Object.entries(relationship.special_relations || {})) {
    if (!relationships_text(name) || ['恋人', '仅朋友', '朋友'].includes(name)) continue;
    push(name, fact?.basis, fact?.since);
  }
  // The ordinary friendship label need not compete with more specific facts.
  if (!badges.length && relationship.commitment === '仅朋友') push('朋友', relationship.commitment_basis);
  return badges.sort((a, b) => a.rank - b.rank || a.name.localeCompare(b.name, 'zh-CN'));
}
function relationshipMeters(relationship = {}) {
  const evaluated = !!relationships_text(relationship.recognition_basis);
  return [
    { key: 'bond', name: '亲近', value: score(relationship.bond), display: String(score(relationship.bond)), tone: 'blue' },
    { key: 'romance', name: '爱恋', value: score(relationship.romance), display: String(score(relationship.romance)), tone: 'rose' },
    { key: 'recognition', name: '认可', value: evaluated ? score(relationship.recognition) : 0, display: evaluated ? String(score(relationship.recognition)) : '未评价', tone: 'gold' },
  ];
}

