;// ./角色卡工程/运行源码/cg-asset-source.mjs

function createEventCgAssetLoader({tavern,owner}){
 return async asset=>{
  if(!/^assets\/images\/[a-f0-9]{64}\.png$/.test(asset.uri))throw Error('事件CG资源路径无效');
  const base=companionAssetBase(new URL('/user/files/crossover-galgame/',owner.location.href).href,tavern),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
  try{const result=await owner.fetch(new URL(asset.uri,base).href,{credentials:'omit',signal:controller.signal});if(!result.ok)throw Error('事件CG加载失败：'+result.status);return await result.arrayBuffer();}
  finally{clearTimeout(timer);}
 };
}

