;// ./前端工程/src/stage-entry.mjs


function installStageUi({host,source,eventOn}){
 const owner=window.parent,base=companionAssetBase(new URL('/user/files/crossover-galgame/',owner.location.href).href,host.SillyTavern);
 const context=host.SillyTavern.getContext?.()||host.SillyTavern,card=context.characters?.[context.characterId];
 const video=(card?.data?.extensions?.crossover_cloud||card?.extensions?.crossover_cloud)?.video;
 if(video?.url&&video?.file)source=source.replace('assets/media/'+video.file,video.url);
 return installPersistentStage({owner,host,source,base,eventOn,eventTypes:host.tavern_events,mvuEvents:host.Mvu.events});
}

