const __teacherBody="<content>\n【场景：教师办公室】\n放学后的办公室里，打印机还在一张张吐纸。平冢静把红笔搁在摊开的作文旁，转过椅子，白大褂的下摆擦过桌角。\n平冢静[常态]：「新学期也开始一阵子了。这学期，你有什么打算？」\n她拿起杯子，发现咖啡已经空了。\n平冢静[常态]：「社团、想学的东西，或者有什么一直想做却没动手的事，都可以说。」\n桌边压着几张招新传单。她从下面抽出一张活动室分布图，用笔帽点了点其中一处。\n平冢静[认真]：「我担任顾问的奉仕部就在这里。有人带着烦恼来，有人想完成一件愿望，但更多时候只是一群逃避回家的问题儿童聚在一起喝茶罢了。」\n说到这里，她嘴角忍不住动了一下。\n平冢静[微笑]：「部长是雪之下雪乃。脑子很好，但是性格有点别扭，也许你们能合得来，亦或者...」\n她合上笔帽，把分布图往桌沿推近了一点。\n平冢静[常态]：「想玩音乐可以去轻音部，对实验有兴趣就去科学部。还有别的想法，我也能帮你问问。」\n走廊上响起几声招呼，很快又远了。平冢静看了一眼钟，抬眼望来。\n平冢静[微笑]：「我正好要去奉仕部看看。怎么样，要跟我一起去，还是先说说你想去哪儿？」\n1. 跟老师去奉仕部看看。\n2. 请老师介绍其他社团。\n3. 和老师谈谈自己的安排。\n</content>";

$(async()=>{
 await waitGlobalInitialized('Mvu');
 await waitGlobalInitialized('CrossoverMvuCoreContract');
 const coreContract=window.CrossoverMvuCoreContract;
 const {installMvuIntegration,createOpeningHostAdapter,createTavernCgJudge,installCompanionGeneration,installCompanionUi,installStageUi,createEventCgAssetLoader}=__CrossoverGalgameRuntime;
 const integration=installMvuIntegration({Schema,registerMvuSchema,coreContract,eventOn,eventMakeFirst,eventMakeLast,
 cgOptions:__cgEnabled?{z,catalog:__cgCatalog,policies:__cgPolicies,eventCatalog:__eventCgCatalog,loadAsset:createEventCgAssetLoader({tavern:SillyTavern,owner:window.parent}),judge:typeof generateRaw==='function'?createTavernCgJudge(generateRaw):null}:null,
 identityOptions:{catalog:__castCatalog,profiles:__castProfiles,initialCommunication:__initialCommunication},
 openingOptions:{catalog:__openingCatalog,autoOpening:{bootstrap_body:'创建角色',teacher_body:__teacherBody,character_openings:__characterOpenings},adapter:createOpeningHostAdapter({getContext:()=>SillyTavern,getChatMessages,getMessageObject:id=>SillyTavern.chat[id],setChatMessages,fetchImpl:(url,options)=>window.parent.fetch(url,options)})},
 mvuEvents:Mvu.events,tavernEvents:typeof tavern_events==='object'?tavern_events:{},eventEmit,isGenerating:()=>typeof builtin==='object'&&builtin.duringGenerating?.()===true,getChatMessages,getCurrentChatId:()=>SillyTavern.getCurrentChatId(),getMessageObject:id=>SillyTavern.chat[id],substituteMacros:typeof substitudeMacros==='function'?substitudeMacros:value=>value,updateVariablesWith,getVariables,onError:error=>{console.error(error);toastr.error(String(error.message??error),'校园状态保存失败');}});
 initializeGlobal('CrossoverMvu',integration);
 const companionGeneration=installCompanionGeneration({integration,getChatMessages,getCurrentChatId:()=>SillyTavern.getCurrentChatId(),getVariables,eventOn,eventTypes:typeof tavern_events==='object'?tavern_events:{}});
 const uiHost={Mvu,CrossoverMvu:integration,CrossoverMvuCoreContract:coreContract,waitGlobalInitialized,getChatMessages,getVariables,SillyTavern,generateRaw:typeof generateRaw==='function'?generateRaw:null,createChatMessages,triggerSlash,getCharWorldbookNames,getWorldbookNames,eventEmit,tavern_events:typeof tavern_events==='object'?tavern_events:{},builtin:typeof builtin==='object'?builtin:window.builtin,parent:window.parent};
 const companionUi=installCompanionUi({integration,host:uiHost});
 initializeGlobal('CrossoverCompanionUi',companionUi);
 const stageUi=installStageUi({host:uiHost,source:__stageFrontendSource,eventOn});
 $(window).on('pagehide',()=>{stageUi.stop();companionGeneration.stop();companionUi.stop();integration.stop();});
});
